    floor=min(F) if F else None
    out=[row[:] for row in inp]
    if floor is None: return out
    for r in range(h):
        for c in range(w):
            if inp[r][c]!=4: continue
            j=r+1
            if j<h and j<floor: out[j][c]=4
            if floor-r==1:
                k=1
                while True:
                    rr,cc=j-k,c-k
                    if cc<0 or not(0<=rr<h): break
                    out[rr][cc]=4
                    k+=1
                k=1
                while True:
                    rr,cc=j-k,c+k
                    if cc>=w or not(0<=rr<h): break
                    out[rr][cc]=4
                    k+=1
    return out
